# The new cachedmethod function
new_cachedmethod = '''def cachedmethod(cache, key=keys.methodkey, lock=None, condition=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """

    def decorator(method):
        if condition is not None:

            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                with condition:
                    try:
                        return c[k]
                    except KeyError:
                        pass  # key not found
                v = method(self, *args, **kwargs)
                with condition:
                    # in case of a race, prefer the item already in the cache
                    try:
                        return c.setdefault(k, v)
                    except ValueError:
                        return v  # value too large

            def clear(self):
                c = cache(self)
                if c is not None:
                    with condition:
                        c.clear()

        elif lock is not None:

            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                # in case of a race, prefer the item already in the cache
                try:
                    with lock(self):
                        return c.setdefault(k, v)
                except ValueError:
                    return v  # value too large

            def clear(self):
                c = cache(self)
                if c is not None:
                    with lock(self):
                        c.clear()

        else:

            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v

            def clear(self):
                c = cache(self)
                if c is not None:
                    c.clear()

        wrapper.cache = cache
        wrapper.cache_key = key
        wrapper.cache_lock = condition or lock
        wrapper.cache_clear = clear

        return functools.update_wrapper(wrapper, method)

    return decorator'''

